//! Passive Text children preserve native identity, records and live ranges.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse_loaded_document_with_scripting("<body><noscript id=host>held</noscript><button id=button><noscript id=guard>guarded</noscript></button><p id=out>Real</p>",true,&||Ok(())).unwrap();let mut f=Forms::new(&d);let mut p=Page::new();let l=crate::navigation::address("https://noscript-text-fragments.test/",&crate::navigation::Location::home()).unwrap();p.set_location(&l);p.set_resource_base(&l);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
fn refusal(d:&mut Document,f:&mut Forms,p:&mut Page,code:&str)->String{let source=format!("var caughtFailure=null;try{{{code}}}catch(e){{caughtFailure=e.name+': '+e.message;}}");match p.runtime.execute(&source,&mut Bridge{doc:d,forms:f,state:&mut p.state}){Err(e)=>e,Ok(_)=>{let value=p.runtime.execute("caughtFailure",&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();let Value::String(message)=value else{panic!("Expected an actual native refusal: {value:?}")};message}}}


#[test]
fn noscript_text_fragments_append_drains_actual_donor_and_records_exact_utf16_and_ranges(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var host=document.getElementById('host'),original=host.firstChild,donor=document.createDocumentFragment(),a=document.createTextNode('A\udfff'),b=document.createTextNode('\ud800B'),watch=new MutationObserver(function(){}),range=document.createRange();donor.appendChild(a);donor.appendChild(b);range.setStart(b,1);range.setEnd(b,2);watch.observe(donor,{childList:true});watch.observe(host,{childList:true});if(host.appendChild(donor)!==donor)throw 'fragment return';var rs=watch.takeRecords();if(donor.firstChild!==null||donor.parentNode!==null||host.childNodes.length!==3||host.firstChild!==original||original.nextSibling!==a||a.nextSibling!==b||host.lastChild!==b||a.parentNode!==host||b.parentNode!==host||a.ownerDocument!==document||b.ownerDocument!==document||host.innerHTML!=='heldA\udfff\ud800B'||range.startContainer!==donor||range.endContainer!==donor||range.startOffset||range.endOffset||rs.length!==2||rs[0].target!==donor||rs[0].removedNodes.length!==2||rs[0].removedNodes[0]!==a||rs[0].removedNodes[1]!==b||rs[1].target!==host||rs[1].addedNodes.length!==2||rs[1].addedNodes[0]!==a||rs[1].addedNodes[1]!==b||rs[1].previousSibling!==original||rs[1].nextSibling!==null)throw 'actual Text fragment append';if(document.querySelectorAll('script').length)throw 'passive fragment';"#);assert!(p.take_dynamic_scripts().is_empty());assert!(p.take_dynamic_stylesheets().is_empty());
}
#[test]
fn noscript_text_fragments_insert_replace_empty_preserve_real_sibling_records_and_returns(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var host=document.getElementById('host'),original=host.firstChild,donor=document.createDocumentFragment(),a=document.createTextNode('first'),b=document.createTextNode('<b>literal</b>'),watch=new MutationObserver(function(){});donor.appendChild(a);donor.appendChild(b);watch.observe(donor,{childList:true});watch.observe(host,{childList:true});if(host.insertBefore(donor,original)!==donor)throw 'insert fragment return';var rs=watch.takeRecords();if(host.firstChild!==a||a.nextSibling!==b||b.nextSibling!==original||rs.length!==2||rs[0].target!==donor||rs[1].target!==host||rs[1].addedNodes[0]!==a||rs[1].addedNodes[1]!==b||rs[1].previousSibling!==null||rs[1].nextSibling!==original)throw 'actual fragment before';var next=document.createDocumentFragment(),x=document.createTextNode('x'),y=document.createTextNode('y');next.appendChild(x);next.appendChild(y);watch.observe(next,{childList:true});if(host.replaceChild(next,b)!==b)throw 'replace fragment return';rs=watch.takeRecords();if(b.parentNode!==null||b.data!=='<b>literal</b>'||next.firstChild!==null||a.nextSibling!==x||x.nextSibling!==y||y.nextSibling!==original||rs.length!==2||rs[0].target!==next||rs[0].removedNodes[0]!==x||rs[0].removedNodes[1]!==y||rs[1].target!==host||rs[1].removedNodes[0]!==b||rs[1].addedNodes[0]!==x||rs[1].addedNodes[1]!==y||rs[1].previousSibling!==a||rs[1].nextSibling!==original)throw 'actual fragment replace';var empty=document.createDocumentFragment();watch.observe(empty,{childList:true});host.appendChild(empty);if(watch.takeRecords().length)throw 'empty fragment append records';if(host.replaceChild(empty,x)!==x)throw 'empty replace return';rs=watch.takeRecords();if(x.parentNode!==null||a.nextSibling!==y||rs.length!==1||rs[0].target!==host||rs[0].removedNodes[0]!==x||rs[0].addedNodes.length||rs[0].previousSibling!==a||rs[0].nextSibling!==y)throw 'empty fragment replacement';"#);assert!(p.take_dynamic_scripts().is_empty());
}
#[test]
fn noscript_text_fragments_mixed_native_ancestor_and_membership_refusals_keep_donor_and_host(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var host=document.getElementById('host'),original=host.firstChild,guarded=document.getElementById('guard'),donor=document.createDocumentFragment(),text=document.createTextNode('literal'),mixed=document.createDocumentFragment(),span=document.createElement('span'),missing=document.createTextNode('missing'),watch=new MutationObserver(function(){});donor.appendChild(text);mixed.appendChild(document.createTextNode('prefix'));mixed.appendChild(span);watch.observe(document.body,{childList:true,subtree:true});watch.observe(donor,{childList:true});watch.observe(mixed,{childList:true});");p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;
 for(code,category)in[("host.appendChild(mixed);","inert resource subtrees"),("host.replaceChild(mixed,original);","inert resource subtrees"),("guarded.appendChild(donor);","inert resource subtrees"),("host.insertBefore(donor,missing);","NotFoundError")]{p.begin_job();let e=refusal(&mut d,&mut f,&mut p,code);assert!(e.contains(category),"{code}: {e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);p.begin_job();run(&mut d,&mut f,&mut p,"if(host.firstChild!==original||donor.firstChild!==text||text.parentNode!==donor||mixed.childNodes.length!==2||span.parentNode!==mixed||watch.takeRecords().length)throw 'fragment guard atomic';");}p.begin_job();run(&mut d,&mut f,&mut p,"document.getElementById('out').textContent='Recovered';");assert!(p.take_dynamic_scripts().is_empty());assert!(p.take_dynamic_stylesheets().is_empty());
}
#[test]
fn noscript_text_fragments_copy_work_retained_refusals_preserve_donor_range_and_recover(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var host=document.getElementById('host'),original=host.firstChild,donor=document.createDocumentFragment(),text=document.createTextNode('new'),watch=new MutationObserver(function(){}),range=document.createRange();donor.appendChild(text);for(var i=1;i<128;i++)donor.appendChild(document.createTextNode('x'));range.setStart(text,1);range.setEnd(text,2);watch.observe(donor,{childList:true});watch.observe(host,{childList:true});");p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;let limit=p.state.retained_limit;
 for mode in 0..3{p.begin_job();match mode{0=>p.state.copy_work=0,1=>p.state.host_work=0,_=>p.state.retained_limit=p.state.retained};let e=refusal(&mut d,&mut f,&mut p,"host.appendChild(donor);").to_ascii_lowercase();assert!(match mode{0=>e.contains("dom string work limit"),1=>e.contains("dom work limit"),_=>e.contains("allowance")||e.contains("retained")||e.contains("storage")},"{mode}: {e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);p.state.retained_limit=limit;p.begin_job();run(&mut d,&mut f,&mut p,"if(host.firstChild!==original||host.childNodes.length!==1||donor.firstChild!==text||text.parentNode!==donor||watch.takeRecords().length||range.startContainer!==text||range.endContainer!==text||range.startOffset!==1||range.endOffset!==2)throw 'fragment quota atomic';");}p.begin_job();run(&mut d,&mut f,&mut p,"host.appendChild(donor);var rs=watch.takeRecords();if(host.childNodes.length!==129||host.childNodes[1]!==text||donor.firstChild!==null||rs.length!==2||rs[0].removedNodes.length!==128||rs[0].removedNodes[0]!==text||rs[1].addedNodes.length!==128||rs[1].addedNodes[0]!==text||range.startContainer!==donor||range.endContainer!==donor||range.startOffset||range.endOffset)throw 'fresh fragment recovery';");assert!(p.take_dynamic_scripts().is_empty());assert!(p.take_dynamic_stylesheets().is_empty());
}
